// Illustrative pilot targets. A course must validate these before real pace decisions.
export function holeTargets(holes=[],total=245){const weights=Array.from({length:18},(_,i)=>({3:11,4:14,5:17})[holes[i]?.par]||14),sum=weights.reduce((a,b)=>a+b,0),raw=weights.map(n=>n*total/sum),targets=raw.map(Math.floor),order=raw.map((n,i)=>({i,fraction:n%1})).sort((a,b)=>b.fraction-a.fraction);let remaining=total-targets.reduce((a,b)=>a+b,0);for(let i=0;i<remaining;i++)targets[order[i%18].i]++;return targets;}

export function validTargets(value){return Array.isArray(value)&&value.length===18&&value.every(n=>Number.isInteger(n)&&n>=5&&n<=30);}
export function progressAt(elapsed,targets){let left=Math.max(0,elapsed);for(let i=0;i<18;i++){if(left<targets[i])return i+left/targets[i];left-=targets[i];}return 17.98;}
export function delayWindow(targets=holeTargets()){const entered=targets.slice(0,4).reduce((a,b)=>a+b,0)-10,target=targets[4];return {hole:5,groupId:7,entered,target,extra:16,alertAt:entered+target+3,clearAt:entered+target+16};}
export function delayIncident(minutes,choice='auto',targets=holeTargets()){const w=delayWindow(targets),active=choice==='queue'||choice==='auto'&&minutes>=w.alertAt&&minutes<w.clearAt;return {...w,active,elapsed:Math.max(0,(choice==='queue'?minutes:Math.min(minutes,w.clearAt))-w.entered),over:Math.max(0,(choice==='queue'?minutes:Math.min(minutes,w.clearAt))-w.entered-w.target),reason:'Scripted course note: recovery shots and a temporarily blocked green.',evidence:'Time on hole exceeds its demo target; location alone does not establish the cause.'};}
export function distanceYards(a,b){if(!a||!b)return null;const rad=n=>n*Math.PI/180,dLat=rad(b[0]-a[0]),dLon=rad(b[1]-a[1]);const h=Math.sin(dLat/2)**2+Math.cos(rad(a[0]))*Math.cos(rad(b[0]))*Math.sin(dLon/2)**2;return Math.round(6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))*1.0936133);}
export function readTargets(id,holes,total){try{const saved=JSON.parse(globalThis.localStorage?.getItem('ff-targets-'+id)||'null');if(validTargets(saved))return saved;}catch{}return holeTargets(holes,total);}
export function saveTargets(id,targets){if(!validTargets(targets))throw new Error('Enter 5–30 whole minutes for each of the 18 holes.');try{globalThis.localStorage?.setItem('ff-targets-'+id,JSON.stringify(targets));return !!globalThis.localStorage;}catch{return false;}}

export function finishMinute(group,targets,choice='auto'){if(group.stale)return null;const total=targets.reduce((a,b)=>a+b,0),expected=targets.slice(0,group.hole-1).reduce((a,b)=>a+b,0)+group.fraction*targets[group.hole-1],observedDelay=choice==='gap'?10:Math.max(0,Math.round(group.elapsed-expected));return 510+total+observedDelay;}

// A deterministic service-time model. Green-clearance headway is a demo capacity
// parameter, not a physical safety distance or permission to play a shot.
export function roundSchedule(targets,choice='auto',minutes=0){const groups=[];for(let id=4;id<=11;id++){const cells=[];for(let h=0;h<18;h++){const entry=h?cells[h-1].exit:(id-8)*10,normalExit=entry+targets[h],source=id===7&&h===4&&(choice==='auto'||choice==='queue'),extra=source?16:0,preceding=groups.at(-1)?.cells[h],exit=Math.max(normalExit+extra,preceding?preceding.exit+4:-Infinity,source&&choice==='queue'?minutes+1:-Infinity);cells.push({entry,exit,normalExit,delay:Math.max(0,exit-normalExit),release:exit-targets[h]*.35,approach:entry+targets[h]*.65});}groups.push({id,cells});}return groups;}
